scripts.无相对话.txt:
// 与无相的对话

	If ($Event == 370) @Event370;
	If ($Event == 380) @Event370;
	If ($Event == 390) @Event370;
	If ($Event == 400) @Event370;
	Return;
	
@Event370:
	Say("无相：少林有七十二绝技，谁要是学透其中的一种就可天下无敌。只是出家人的武功再好，也只不过用来强身健体，多活几年罢了。", 73);
	Return;

scripts.张琳心对话.txt:
// 张琳心的同伴对话

	If ($Event == 370) @Event370;
	If ($Event == 380) @Event380;
	If ($Event == 390) @Event390;
	If ($Event == 400) @Event400;
	If ($Event == 410) @Event410;
	If ($Event == 420) @Event420;
	
	Return;
	
@Event370:
	Say("张琳心：咦，无虚大师好像不在大雄宝殿。", 21);
	Return;
			
@Event380:
	Say("张琳心：我们去达摩堂找无虚大师吧。", 21);			
	Say("独孤剑：好。", 1);
	Return;
	
@Event390:	
	Say("张琳心：到底偷袭无虚大师的人是谁呢？", 21);	
	Return;		
	
@Event400:
	Say("独孤剑：那黄剑堂堂主是谁呢？", 1);
	Say("张琳心：独孤哥哥，你别犯愁，我自有妙计引他出来，我们先去找无虚大师吧。", 21);
	Return;	
	
@Event410:
	Say	("张琳心：独孤哥哥，我们去藏经阁拜访无穷大师吧，说不定有什么意想不到的收获呢。", 21);
	Return;	
	
@Event420:
	Say("张琳心：我们下山吧！", 21);
	Return;

scripts.无虚大师对话.txt:
//和无虚对话

	Say("无虚大师：两位施主请多保重，老衲恕不远送。", 56);
	Return;

scripts.普通弟子对话.txt:
// 与普通弟子的对话

	If ($Event >= 410) @Event410;
	
	Say("和尚：阿弥陀佛，我们正在念经修行，请施主不要打扰。", 0);
	Return;
	
@Event410:
	GetRandNum($Talkheshang,0,1);
	If ($Talkheshang == 0) @Talk0;
	If ($Talkheshang == 1) @Talk1;
@Talk0:
	Say("和尚：阿弥陀佛，多谢施主替少林化解了一场无妄之灾。", 0);
	Return;
@Talk1:	
	Say("和尚：无相师叔居然是五色教的奸细，真是没想到！", 0);
	Return;

